def format_attribute(attr: Any) -> object {
    res = attr.replace("-", " ");
    res = res.capitalize();
    res = res.replace(" ip ", " IP ");
    res = res.replace(" mac ", " MAC ");
    res = res.replace(" mtu", " MTU");
    return res;
}

"""Convert time in seconds to a human readable string"""
def _hr_time(seconds: Any) -> object {
    minutes = seconds // 60;
    if not minutes {
        return '{}s'.format(seconds);
    }
    hours = minutes // 60;
    if not hours {
        seconds -= minutes * 60;
        return '{}m {}s'.format(minutes, seconds);
    }
    days = hours // 24;
    if not days {
        minutes -= hours * 60;
        return '{}h {}m'.format(hours, minutes);
    }
    years = days // 365;
    if not years {
        hours -= days * 24;
        return '{}d {}h'.format(days, hours);
    } else {
        days -= years * 365;
        return '{}y {}d'.format(years, days);
    }
}

